import{_ as a,o,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Regiones corporales e integridad","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/body-regions.md","filePath":"es/game-design/combat/body-regions.md"}'),t={name:"es/game-design/combat/body-regions.md"};function d(n,e,s,c,l,p){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="body-regions-and-integrity" tabindex="-1">Regiones corporales e integridad <a class="header-anchor" href="#body-regions-and-integrity" aria-label="Enlace permanente a &quot;Regiones corporales e integridad&quot;">​</a></h1><p><strong>Estado del diseño: Aceptado para el modelo y la normalización/ciclo de vida experimentales. Implementación: cuerpo transitorio del jugador y puntos de integración del ciclo de vida de Stage 2A; validación de juego pendiente.</strong></p><p>Las siete regiones anatómicas son <code>Head</code>, <code>Neck</code>, <code>Torso</code>, <code>LeftArm</code>, <code>RightArm</code>, <code>LeftLeg</code> y <code>RightLeg</code>. Izquierda/derecha siempre se refiere a la anatomía del objetivo. Cada región tiene integridad funcional independiente; Hits globales siguen siendo la reserva de vida/muerte. Siete regiones <strong>no</strong> crean siete sistemas de muerte independientes.</p><p>Solo la región del impacto real recibe el Local Trauma primario. Las mangas o perneras compartidas no fusionan el estado corporal izquierdo/derecho. <code>AnatomyProfile</code> es un concepto de juego, no una categoría de cuerpo para animaciones.</p><h3 id="accepted-experimental-slice-0-scale" tabindex="-1">Escala experimental de Slice 0 con estado Aceptado <a class="header-anchor" href="#accepted-experimental-slice-0-scale" aria-label="Enlace permanente a &quot;Escala experimental de Slice 0 con estado Aceptado&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Integridad</th><th>Condición</th></tr></thead><tbody><tr><td>76–100</td><td>Healthy</td></tr><tr><td>51–75</td><td>Wounded</td></tr><tr><td>26–50</td><td>Injured</td></tr><tr><td>1–25</td><td>Severe</td></tr><tr><td>0</td><td>Disabled</td></tr></tbody></table><p>Estos valores son una estructura de prueba, no equilibrio definitivo. La política aprobada limitada a la sesión inicializa el cuerpo sano, lo reinicia tras resurrección exitosa/reingreso/reinicio/reinicio corporal autorizado y persiste ante cambios de mapa o Combatant. La muerte lo invalida; una resurrección fallida no debe curar un cuerpo vivo. Este slice no incluye recuperación pasiva, temporizador de extremidades ni persistencia.</p><p>El reinicio corporal no debe curar HP globales, reparar equipo ni reequipar automáticamente un escudo. Stage 2A usa estado transitorio, registra trauma cuerpo a cuerpo real y aplica reglas del ciclo de sesión/muerte/resurrección. No hay un comando de reinicio autorizado en esta etapa mínima. <strong>Carencia:</strong> observar acumulación y ciclo de vida en una prueba de juego de dos personas.</p><h2 id="related-combat-foundation" tabindex="-1">Fundamento de combate relacionado <a class="header-anchor" href="#related-combat-foundation" aria-label="Enlace permanente a &quot;Fundamento de combate relacionado&quot;">​</a></h2><p>La <a href="/Syrolands-Public/es/guide/combat/limbs-and-trauma.html">guía del jugador: Extremidades y trauma</a> resume estas reglas. Las <a href="/Syrolands-Public/es/game-design/combat/damage.html#proposed-injuries-and-healing">propuestas ampliadas de lesiones y Healing</a> no cambian las siete regiones, sus umbrales ni el ciclo de vida anterior. La aplicación a seres no humanos y objetivos grandes corresponde a <a href="/Syrolands-Public/es/game-design/creatures.html">anatomía de criaturas</a>, no a categorías de cuerpos para animaciones.</p>',10)])])}const g=a(t,[["render",d]]);export{m as __pageData,g as default};
